demo.querySelectorAll('select').forEach(select=>select.addEventListener('change',()=>showDemo(coverOptions(demo.querySelector('.demo-occasion').value,demo.querySelector('.demo-format').value)[0])));demo.querySelector('.demo-covers').addEventListener('click',()=>catalog.open(demoData.occasion,demoData.format));demo.querySelector('.demo-open').addEventListener('click',previewGift);demo.querySelector('.demo-create').addEventListener('click',()=>requestCreation(coverOptions(demoData.occasion,demoData.format)[0]));
