const openingPicker=document.createElement('label');openingPicker.className='opening-picker';openingPicker.textContent='A surpresa antes do presente';const openingSelect=document.createElement('select');openingSelect.id='opening-style';for(const [key,label] of Object.entries({default:'Laço clássico',natal:'Natal · chegada do carinho',aniversario:'Aniversário · festa na caixa',casamento:'Casamento · um sim delicado',familia:'Família · abraço de presente',amor:'Amor · carta com carinho',pascoa:'Páscoa · pequena surpresa',conquistas:'Conquistas · hora de celebrar',pet:'Pet · companhia feliz'}))openingSelect.add(new Option(label,key));openingSelect.value=state.openingStyle||'default';openingSelect.addEventListener('change',()=>{state.openingStyle=openingSelect.value;render();});openingPicker.append(openingSelect);document.querySelector('#creator-step-4').prepend(openingPicker);
